        <script id="global-script">function expandGroup(group) {
  const trigger = group.querySelector('button')
  trigger.setAttribute('aria-expanded', 'true')

  const samp = group.querySelector('samp')
  samp.removeAttribute('hidden')
}

function collapseGroup(group) {
  const trigger = group.querySelector('button')
  trigger.removeAttribute('aria-expanded', 'true')

  const samp = group.querySelector('samp')
  samp.setAttribute('hidden', 'true')
}

function dumperActivate(dumpId, expand) {
  if (expand === true) {
    expandGroup(document.querySelector(`#${dumpId} .dumper-group`))
  } else if (expand === 'all') {
    document.querySelectorAll(`#${dumpId} .dumper-group`).forEach((c) => expandGroup(c))
  }

  document.querySelectorAll(`#${dumpId} .dumper-toggle`).forEach((trigger) => {
    trigger.addEventListener('click', function (event) {
      const target = event.currentTarget
      const parent = target.parentElement
      const isExpanded = !!target.getAttribute('aria-expanded')

      if (isExpanded) {
        collapseGroup(parent)
        if (event.metaKey) {
          parent.querySelectorAll('.dumper-group').forEach((c) => collapseGroup(c))
        }
      } else {
        expandGroup(parent)
        if (event.metaKey) {
          parent.querySelectorAll('.dumper-group').forEach((c) => expandGroup(c))
        }
      }
    })
  })
}</script>
<script id="layout-script">function usesDarkMode() {
  let youchTheme = localStorage.getItem('youch-theme')
  let hasDarkMode = false
  if (youchTheme === null) {
    hasDarkMode = window.matchMedia('(prefers-color-scheme: dark)').matches
  } else if (youchTheme === 'dark') {
    hasDarkMode = true
  }
  return hasDarkMode
}

function onContentLoaded(listener) {
  if (document.readyState !== 'loading') {
    listener()
    return
  }
  document.addEventListener('DOMContentLoaded', listener)
}

document.documentElement.classList.add(usesDarkMode() ? 'dark' : 'light')
</script>
<script id="header-script">function toggleTheme(input) {
  if (input.checked) {
    document.documentElement.classList.add('dark')
    localStorage.setItem('youch-theme', 'dark')
  } else {
    document.documentElement.classList.remove('dark')
    localStorage.setItem('youch-theme', 'light')
